#!/usr/bin/env python3
# GENERATED by tools/sync_skills.py from mcp-server/src/mpesa_mcp/validation.py - edit the source, not this copy.
"""Daraja request-body rules, shared by the MCP server and the skills' validate_request.py.

Stdlib only: tools/sync_skills.py copies this file into skills as daraja_validation.py.
APIs: stk, stk_query, c2b_register, c2b_simulate, b2c, b2pochi, b2b, tax,
      status, balance, reversal, qr, ratiba
"""

from __future__ import annotations

import base64
import re

PHONE = re.compile(r"^254[17]\d{8}$")
TIMESTAMP = re.compile(r"^\d{14}$")
SHORTCODE = re.compile(r"^\d{5,7}$")
C2B_FORBIDDEN = ("mpesa", "m-pesa", "safaricom", "exec", "cmd", "sql", "query")

REQUIRED = {
    "stk": ["BusinessShortCode", "Password", "Timestamp", "TransactionType", "Amount", "PartyA",
            "PartyB", "PhoneNumber", "CallBackURL", "AccountReference", "TransactionDesc"],
    "stk_query": ["BusinessShortCode", "Password", "Timestamp", "CheckoutRequestID"],
    "c2b_register": ["ShortCode", "ResponseType", "ConfirmationURL", "ValidationURL"],
    "c2b_simulate": ["ShortCode", "CommandID", "Amount", "Msisdn"],
    "b2c": ["OriginatorConversationID", "InitiatorName", "SecurityCredential", "CommandID", "Amount",
            "PartyA", "PartyB", "Remarks", "QueueTimeOutURL", "ResultURL"],
    "b2pochi": ["OriginatorConversationID", "InitiatorName", "SecurityCredential", "CommandID", "Amount",
                "PartyA", "PartyB", "Remarks", "QueueTimeOutURL", "ResultURL"],
    "b2b": ["Initiator", "SecurityCredential", "CommandID", "SenderIdentifierType", "RecieverIdentifierType",
            "Amount", "PartyA", "PartyB", "AccountReference", "Remarks", "QueueTimeOutURL", "ResultURL"],
    "tax": ["Initiator", "SecurityCredential", "CommandID", "SenderIdentifierType", "RecieverIdentifierType",
            "Amount", "PartyA", "PartyB", "AccountReference", "Remarks", "QueueTimeOutURL", "ResultURL"],
    "status": ["Initiator", "SecurityCredential", "CommandID", "PartyA", "IdentifierType", "ResultURL",
               "QueueTimeOutURL", "Remarks"],
    "balance": ["Initiator", "SecurityCredential", "CommandID", "PartyA", "IdentifierType", "Remarks",
                "QueueTimeOutURL", "ResultURL"],
    "reversal": ["Initiator", "SecurityCredential", "CommandID", "TransactionID", "Amount", "ReceiverParty",
                 "RecieverIdentifierType", "ResultURL", "QueueTimeOutURL", "Remarks"],
    "qr": ["MerchantName", "RefNo", "Amount", "TrxCode", "CPI", "Size"],
    "ratiba": ["StandingOrderName", "StartDate", "EndDate", "BusinessShortCode", "TransactionType",
               "ReceiverPartyIdentifierType", "Amount", "PartyA", "CallBackURL", "AccountReference",
               "TransactionDesc", "Frequency"],
}

COMMANDS = {
    "stk": ("TransactionType", {"CustomerPayBillOnline", "CustomerBuyGoodsOnline"}),
    "c2b_simulate": ("CommandID", {"CustomerPayBillOnline", "CustomerBuyGoodsOnline"}),
    "b2c": ("CommandID", {"BusinessPayment", "SalaryPayment", "PromotionPayment"}),
    "b2pochi": ("CommandID", {"BusinessPayToPochi"}),
    "b2b": ("CommandID", {"BusinessPayBill", "BusinessBuyGoods", "BusinessPayToBulk",
                          "DisburseFundsToBusiness", "BusinessToBusinessTransfer", "MerchantToMerchantTransfer"}),
    "tax": ("CommandID", {"PayTaxToKRA"}),
    "status": ("CommandID", {"TransactionStatusQuery"}),
    "balance": ("CommandID", {"AccountBalance"}),
    "reversal": ("CommandID", {"TransactionReversal"}),
    "qr": ("TrxCode", {"BG", "PB", "WA", "SM", "SB"}),
    "ratiba": ("TransactionType", {"Standing Order Customer Pay Bill", "Standing Order Customer Pay Marchant"}),
}

# Common misspellings people "fix" that Daraja then rejects or ignores.
SPELLING = {
    "ReceiverIdentifierType": "RecieverIdentifierType",
    "Occasion": "Occassion (B2C v3 / B2Pochi spelling)",
}

URL_FIELDS = ("CallBackURL", "ConfirmationURL", "ValidationURL", "QueueTimeOutURL", "ResultURL")


def validate(api: str, body: dict) -> list[str]:
    errors: list[str] = []
    if api not in REQUIRED:
        return [f"Unknown api {api!r}; choose one of: {', '.join(REQUIRED)}"]

    for field in REQUIRED[api]:
        if body.get(field) in (None, ""):
            errors.append(f"Missing required field {field}")

    for wrong, right in SPELLING.items():
        if wrong in body and api in ("b2b", "tax", "reversal", "b2c", "b2pochi"):
            if wrong == "Occasion" and api not in ("b2c", "b2pochi"):
                continue
            errors.append(f"Field {wrong!r} should be spelled {right}")

    if api in COMMANDS:
        field, allowed = COMMANDS[api]
        if field in body and body[field] not in allowed:
            errors.append(f"{field}={body[field]!r} not valid here; allowed: {sorted(allowed)}")

    if "Amount" in body:
        try:
            amount = float(body["Amount"])
            if amount != int(amount):
                errors.append(f"Amount must be a whole number, got {body['Amount']!r}")
            elif amount < 1:
                errors.append("Amount must be at least 1")
            elif api in ("b2c", "b2pochi") and amount < 10:
                errors.append("B2C amounts below 10 KES are rejected")
        except (TypeError, ValueError):
            errors.append(f"Amount is not numeric: {body['Amount']!r}")

    phone_fields = {"stk": ["PartyA", "PhoneNumber"], "c2b_simulate": ["Msisdn"], "b2c": ["PartyB"],
                    "b2pochi": ["PartyB"], "ratiba": ["PartyA"]}.get(api, [])
    for field in phone_fields:
        if field in body and not PHONE.match(str(body[field])):
            errors.append(f"{field}={body[field]!r} must be 2547XXXXXXXX or 2541XXXXXXXX (no +, no leading 0)")

    for field in ("BusinessShortCode", "ShortCode"):
        if field in body and not SHORTCODE.match(str(body[field])):
            errors.append(f"{field}={body[field]!r} should be a 5-7 digit shortcode")

    for field in URL_FIELDS:
        url = str(body.get(field, ""))
        if url and not url.startswith("https://"):
            errors.append(f"{field} must be a public https:// URL, got {url!r}")
        if url and re.search(r"//(localhost|127\.|10\.|192\.168\.)", url):
            errors.append(f"{field} points at a private/local host Daraja cannot reach: {url!r}")
        if api == "c2b_register" and any(w in url.lower() for w in C2B_FORBIDDEN):
            errors.append(f"{field} contains a word Daraja rejects for C2B URLs ({', '.join(C2B_FORBIDDEN)})")

    if api in ("stk", "stk_query"):
        ts = str(body.get("Timestamp", ""))
        if ts and not TIMESTAMP.match(ts):
            errors.append(f"Timestamp must be YYYYMMDDHHmmss (EAT), got {ts!r}")
        try:
            decoded = base64.b64decode(str(body.get("Password", "")), validate=True).decode()
            sc = str(body.get("BusinessShortCode", ""))
            if sc and not decoded.startswith(sc):
                errors.append("Password does not start with BusinessShortCode once decoded - rebuild it")
            if ts and not decoded.endswith(ts):
                errors.append("Password was built with a different Timestamp than the one in the body")
        except Exception:
            errors.append("Password is not valid base64(BusinessShortCode + Passkey + Timestamp)")

    if api == "stk":
        if len(str(body.get("AccountReference", ""))) > 12:
            errors.append("AccountReference longer than 12 characters (long prompts fail with 1025)")
        if len(str(body.get("TransactionDesc", ""))) > 13:
            errors.append("TransactionDesc longer than 13 characters")
        if body.get("PartyA") and body.get("PhoneNumber") and body["PartyA"] != body["PhoneNumber"]:
            errors.append("PartyA and PhoneNumber normally hold the same paying phone number")

    if api == "tax":
        if str(body.get("PartyB")) != "572572":
            errors.append("Tax remittance PartyB must be KRA's shortcode 572572")
        for f in ("SenderIdentifierType", "RecieverIdentifierType"):
            if f in body and str(body[f]) != "4":
                errors.append(f"{f} must be '4' for tax remittance")

    if api == "b2b":
        expected = "2" if body.get("CommandID") == "BusinessBuyGoods" else "4"
        got = str(body.get("RecieverIdentifierType", expected))
        if got != expected:
            errors.append(f"RecieverIdentifierType should be {expected} for {body.get('CommandID')}")

    if api == "reversal" and str(body.get("RecieverIdentifierType", "11")) != "11":
        errors.append("Reversal RecieverIdentifierType must be '11'")

    if api == "ratiba":
        for f in ("StartDate", "EndDate"):
            if f in body and not re.match(r"^\d{8}$", str(body[f])):
                errors.append(f"{f} must be YYYYMMDD")
        if str(body.get("StartDate", "0")) > str(body.get("EndDate", "99999999")):
            errors.append("EndDate is before StartDate")
        if str(body.get("Frequency")) not in {str(i) for i in range(1, 9)}:
            errors.append("Frequency must be '1'..'8'")
        till = body.get("TransactionType") == "Standing Order Customer Pay Marchant"
        if str(body.get("ReceiverPartyIdentifierType")) != ("2" if till else "4"):
            errors.append("ReceiverPartyIdentifierType must be '2' for Till, '4' for Paybill")

    if api == "status" and not (body.get("TransactionID") or body.get("OriginalConversationID")):
        errors.append("Provide TransactionID or OriginalConversationID")

    return errors
